class Solution {
public:
    double separateSquares(vector<vector<int>>& squares) {
        long long total = 0;
        for (auto& s : squares) {
            long long l = s[2];
            total += l * l;
        }
        double half = total / 2.0;
        double lo = 0.0, hi = 2e9;
        for (int i = 0; i < 100; i++) {
            double mid = (lo + hi) * 0.5;
            double below = 0.0;
            for (auto& s : squares) {
                double y = s[1];
                double l = s[2];
                if (mid <= y) continue;
                if (mid >= y + l) below += l * l;
                else below += l * (mid - y);
            }
            if (below >= half) hi = mid;
            else lo = mid;
        }
        return hi;
    }
};
